-- ONLY disposable Docker database. NEVER run on shared databases.
CREATE DATABASE auxiliares;
USE auxiliares;
CREATE TABLE `FB_USUARIOS` (
  `USER_ID` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `USERNAME` varchar(100) NOT NULL,
  `ROLE` varchar(30) NOT NULL DEFAULT 'collaborator',
  `ENABLED` tinyint(1) NOT NULL DEFAULT 1,
  `MUST_CHANGE_PASSWORD` tinyint(1) NOT NULL DEFAULT 1,
  `PASSWORD_CHANGED_AT` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`USER_ID`),
  UNIQUE KEY `UK_FB_USUARIOS_USERNAME` (`USERNAME`),
  CONSTRAINT `CHK_FB_USUARIOS_USERNAME` CHECK (char_length(trim(`USERNAME`)) between 1 and 100),
  CONSTRAINT `CHK_FB_USUARIOS_ROLE` CHECK (`ROLE` = 'collaborator'),
  CONSTRAINT `CHK_FB_USUARIOS_ENABLED` CHECK (`ENABLED` in (0,1)),
  CONSTRAINT `CHK_FB_USUARIOS_PASSWORD` CHECK (`MUST_CHANGE_PASSWORD` in (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `FB_USUARIOS_CREDENCIALES` (
  `USER_ID` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `PASSWORD_HASH` varchar(255) NOT NULL,
  `CREATED_AT` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `PASSWORD_UPDATED_AT` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`USER_ID`),
  CONSTRAINT `FK_FB_CREDENCIALES_USUARIO` FOREIGN KEY (`USER_ID`) REFERENCES `FB_USUARIOS` (`USER_ID`),
  CONSTRAINT `CHK_FB_CREDENCIALES_HASH` CHECK (char_length(`PASSWORD_HASH`) between 50 and 255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `FB_USUARIOS_SESIONES` (
  `SESSION_ID` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `USER_ID` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `TOKEN_HASH` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `CREATED_AT` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `LAST_ACTIVITY_AT` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `EXPIRES_AT` datetime(6) NOT NULL,
  `REVOKED_AT` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`SESSION_ID`),
  UNIQUE KEY `UK_FB_SESIONES_TOKEN` (`TOKEN_HASH`),
  KEY `IDX_FB_SESIONES_USUARIO` (`USER_ID`),
  KEY `IDX_FB_SESIONES_EXPIRA` (`EXPIRES_AT`),
  CONSTRAINT `FK_FB_SESIONES_USUARIO` FOREIGN KEY (`USER_ID`) REFERENCES `FB_USUARIOS` (`USER_ID`),
  CONSTRAINT `CHK_FB_SESIONES_FECHAS` CHECK (`EXPIRES_AT` > `CREATED_AT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `FB_LOGIN_INTENTOS` (
  `ID_INTENTO` bigint(20) NOT NULL AUTO_INCREMENT,
  `IDENTIFICADOR_HASH` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `IP_HASH` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `FECHA_INTENTO` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `EXITOSO` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID_INTENTO`),
  KEY `IDX_LOGIN_IDENTIFICADOR_FECHA` (`IDENTIFICADOR_HASH`,`FECHA_INTENTO`),
  KEY `IDX_LOGIN_IP_FECHA` (`IP_HASH`,`FECHA_INTENTO`),
  CONSTRAINT `CHK_LOGIN_EXITOSO` CHECK (`EXITOSO` in (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `FB_PERSONAS` (
  `ID_PERSONA` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_PERSONA_CP` bigint(20) DEFAULT NULL,
  `NOMBRE_COMPLETO` varchar(200) NOT NULL,
  `TIPO_DOCUMENTO` varchar(20) NOT NULL,
  `DOCUMENTO` varchar(30) NOT NULL,
  `DOCUMENTO_NORMALIZADO` varchar(30) GENERATED ALWAYS AS (ucase(replace(replace(replace(trim(`DOCUMENTO`),'.',''),'-',''),' ',''))) STORED,
  `FECHA_ALTA` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `FECHA_MODIFICACION` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`ID_PERSONA`),
  UNIQUE KEY `UK_FB_PERSONAS_CP` (`ID_PERSONA_CP`),
  KEY `IDX_FB_PERSONAS_DOCUMENTO` (`TIPO_DOCUMENTO`,`DOCUMENTO_NORMALIZADO`),
  CONSTRAINT `CHK_FB_PERSONAS_NOMBRE` CHECK (char_length(trim(`NOMBRE_COMPLETO`)) > 0),
  CONSTRAINT `CHK_FB_PERSONAS_DOCUMENTO` CHECK (char_length(trim(`DOCUMENTO`)) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `FB_CIU_CONSULTAS_WEB` (
  `ID_CONSULTA` bigint(20) NOT NULL AUTO_INCREMENT,
  `PADRON` varchar(30) NOT NULL,
  `PADCOD` bigint(20) DEFAULT NULL,
  `LOCALIDAD_PADRON` varchar(100) NOT NULL,
  `NOMBRE_COMPLETO` varchar(200) NOT NULL,
  `REL_COD` char(3) DEFAULT NULL,
  `TIPO_DOCUMENTO` varchar(20) NOT NULL,
  `DOCUMENTO` varchar(30) NOT NULL,
  `DOMICILIO_CALLE` varchar(200) DEFAULT NULL,
  `DOMICILIO_PUERTA` varchar(30) DEFAULT NULL,
  `DOMICILIO_BLOCK` varchar(50) DEFAULT NULL,
  `DOMICILIO_APTO` varchar(50) DEFAULT NULL,
  `DOMICILIO_LOCALIDAD` varchar(100) DEFAULT NULL,
  `DOMICILIO_DEPARTAMENTO` varchar(100) DEFAULT NULL,
  `TELEFONO_1` varchar(30) NOT NULL,
  `TIPO_TELEFONO_1` varchar(10) NOT NULL,
  `TELEFONO_2` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_2` varchar(10) DEFAULT NULL,
  `TELEFONO_3` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_3` varchar(10) DEFAULT NULL,
  `TELEFONO_4` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_4` varchar(10) DEFAULT NULL,
  `TELEFONO_5` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_5` varchar(10) DEFAULT NULL,
  `MAIL_1` varchar(254) NOT NULL,
  `MAIL_2` varchar(254) DEFAULT NULL,
  `MAIL_3` varchar(254) DEFAULT NULL,
  `MAIL_4` varchar(254) DEFAULT NULL,
  `MAIL_5` varchar(254) DEFAULT NULL,
  `TIPO_CONSULTA` varchar(40) NOT NULL,
  `DESCRIPCION` text NOT NULL,
  `USUARIO_CREADOR_ID` varchar(100) NOT NULL,
  `FECHA_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `FECHA_MODIFICACION` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `VERSION` int(11) NOT NULL DEFAULT 1,
  `USUARIO_MODIFICADOR_ID` varchar(100) DEFAULT NULL,
  `ID_PERSONA` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`ID_CONSULTA`),
  KEY `IDX_CONSULTAS_PADRON` (`LOCALIDAD_PADRON`,`PADRON`),
  KEY `IDX_CONSULTAS_PADCOD` (`PADCOD`),
  KEY `IDX_CONSULTAS_DOCUMENTO` (`TIPO_DOCUMENTO`,`DOCUMENTO`),
  KEY `IDX_CONSULTAS_FECHA` (`FECHA_ALTA`),
  KEY `IDX_CONSULTAS_CREADOR` (`USUARIO_CREADOR_ID`),
  KEY `IDX_FB_CONSULTAS_PERSONA` (`ID_PERSONA`),
  CONSTRAINT `FK_FB_CONSULTAS_PERSONA` FOREIGN KEY (`ID_PERSONA`) REFERENCES `FB_PERSONAS` (`ID_PERSONA`),
  CONSTRAINT `CHK_CONSULTAS_DOCUMENTO_TIPO` CHECK (`TIPO_DOCUMENTO` in ('CEDULA_IDENTIDAD','RUT','OTROS')),
  CONSTRAINT `CHK_CONSULTAS_TIPO` CHECK (`TIPO_CONSULTA` in ('GENERAL','RECLAMO','FALTA_DOCUMENTACION','DECLARACION_METROS')),
  CONSTRAINT `CHK_CONSULTAS_DESCRIPCION` CHECK (char_length(trim(`DESCRIPCION`)) between 20 and 10000),
  CONSTRAINT `CHK_CONSULTAS_NOMBRE` CHECK (char_length(trim(`NOMBRE_COMPLETO`)) between 1 and 200),
  CONSTRAINT `CHK_CONSULTAS_TELEFONO` CHECK (char_length(trim(`TELEFONO_1`)) > 0),
  CONSTRAINT `CHK_CONSULTAS_MAIL` CHECK (char_length(trim(`MAIL_1`)) > 0),
  CONSTRAINT `CHK_CONSULTAS_TEL_TIPO_1` CHECK (`TIPO_TELEFONO_1` in ('FIJO','CELULAR')),
  CONSTRAINT `CHK_CONSULTAS_TEL_TIPO_2` CHECK (`TIPO_TELEFONO_2` is null or `TIPO_TELEFONO_2` in ('FIJO','CELULAR')),
  CONSTRAINT `CHK_CONSULTAS_TEL_TIPO_3` CHECK (`TIPO_TELEFONO_3` is null or `TIPO_TELEFONO_3` in ('FIJO','CELULAR')),
  CONSTRAINT `CHK_CONSULTAS_TEL_TIPO_4` CHECK (`TIPO_TELEFONO_4` is null or `TIPO_TELEFONO_4` in ('FIJO','CELULAR')),
  CONSTRAINT `CHK_CONSULTAS_TEL_TIPO_5` CHECK (`TIPO_TELEFONO_5` is null or `TIPO_TELEFONO_5` in ('FIJO','CELULAR')),
  CONSTRAINT `CHK_CONSULTAS_TEL_PAIR_2` CHECK (`TELEFONO_2` is null and `TIPO_TELEFONO_2` is null or `TELEFONO_2` is not null and `TIPO_TELEFONO_2` is not null),
  CONSTRAINT `CHK_CONSULTAS_TEL_PAIR_3` CHECK (`TELEFONO_3` is null and `TIPO_TELEFONO_3` is null or `TELEFONO_3` is not null and `TIPO_TELEFONO_3` is not null),
  CONSTRAINT `CHK_CONSULTAS_TEL_PAIR_4` CHECK (`TELEFONO_4` is null and `TIPO_TELEFONO_4` is null or `TELEFONO_4` is not null and `TIPO_TELEFONO_4` is not null),
  CONSTRAINT `CHK_CONSULTAS_TEL_PAIR_5` CHECK (`TELEFONO_5` is null and `TIPO_TELEFONO_5` is null or `TELEFONO_5` is not null and `TIPO_TELEFONO_5` is not null),
  CONSTRAINT `CHK_FB_CONSULTAS_VERSION` CHECK (`VERSION` > 0),
  CONSTRAINT `CHK_FB_CONSULTAS_MODIFICADOR` CHECK (`VERSION` = 1 or `USUARIO_MODIFICADOR_ID` is not null and char_length(trim(`USUARIO_MODIFICADOR_ID`)) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Consultas registradas desde Territorio Paysandu';
CREATE TABLE `FB_CONSULTAS_HISTORIAL` (
  `ID_HISTORIAL` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_CONSULTA` bigint(20) NOT NULL,
  `VERSION` int(11) NOT NULL,
  `TIPO_OPERACION` varchar(20) NOT NULL,
  `USUARIO_MODIFICADOR_ID` varchar(100) NOT NULL,
  `DATOS_ANTERIORES` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`DATOS_ANTERIORES`)),
  `DATOS_NUEVOS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`DATOS_NUEVOS`)),
  `FECHA_MODIFICACION` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`ID_HISTORIAL`),
  UNIQUE KEY `UK_HISTORIAL_VERSION` (`ID_CONSULTA`,`VERSION`),
  KEY `IDX_HISTORIAL_CONSULTA` (`ID_CONSULTA`),
  KEY `IDX_HISTORIAL_USUARIO` (`USUARIO_MODIFICADOR_ID`),
  KEY `IDX_HISTORIAL_FECHA` (`FECHA_MODIFICACION`),
  CONSTRAINT `FK_HISTORIAL_CONSULTA` FOREIGN KEY (`ID_CONSULTA`) REFERENCES `FB_CIU_CONSULTAS_WEB` (`ID_CONSULTA`),
  CONSTRAINT `CHK_HISTORIAL_OPERACION` CHECK (`TIPO_OPERACION` in ('CREACION','MODIFICACION')),
  CONSTRAINT `CHK_HISTORIAL_VERSION` CHECK (`VERSION` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `FB_CONTACTOS` (
  `ID_CONTACTO` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_CONSULTA` bigint(20) NOT NULL,
  `TELEFONO_1` varchar(30) NOT NULL,
  `TIPO_TELEFONO_1` varchar(10) NOT NULL,
  `TELEFONO_2` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_2` varchar(10) DEFAULT NULL,
  `TELEFONO_3` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_3` varchar(10) DEFAULT NULL,
  `TELEFONO_4` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_4` varchar(10) DEFAULT NULL,
  `TELEFONO_5` varchar(30) DEFAULT NULL,
  `TIPO_TELEFONO_5` varchar(10) DEFAULT NULL,
  `MAIL_1` varchar(254) NOT NULL,
  `MAIL_2` varchar(254) DEFAULT NULL,
  `MAIL_3` varchar(254) DEFAULT NULL,
  `MAIL_4` varchar(254) DEFAULT NULL,
  `MAIL_5` varchar(254) DEFAULT NULL,
  `FECHA_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `NOMBRE_COMPLETO` varchar(200) NOT NULL,
  `TIPO_DOCUMENTO` varchar(20) NOT NULL,
  `DOCUMENTO` varchar(30) NOT NULL,
  `DOCUMENTO_NORMALIZADO` varchar(30) GENERATED ALWAYS AS (ucase(replace(replace(replace(trim(`DOCUMENTO`),'.',''),'-',''),' ',''))) STORED,
  `USUARIO_MODIFICADOR_ID` varchar(100) NOT NULL,
  `FECHA_MODIFICACION` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `VERSION` int(11) NOT NULL DEFAULT 1,
  `ID_PERSONA` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`ID_CONTACTO`),
  UNIQUE KEY `UK_FB_CONTACTOS_PERSONA` (`TIPO_DOCUMENTO`,`DOCUMENTO_NORMALIZADO`),
  KEY `IDX_FB_CONTACTOS_CONSULTA` (`ID_CONSULTA`),
  KEY `IDX_FB_CONTACTOS_PERSONA` (`ID_PERSONA`),
  CONSTRAINT `FK_FB_CONTACTOS_CONSULTA` FOREIGN KEY (`ID_CONSULTA`) REFERENCES `FB_CIU_CONSULTAS_WEB` (`ID_CONSULTA`),
  CONSTRAINT `FK_FB_CONTACTOS_PERSONA` FOREIGN KEY (`ID_PERSONA`) REFERENCES `FB_PERSONAS` (`ID_PERSONA`),
  CONSTRAINT `CHK_FB_CONTACTOS_VERSION` CHECK (`VERSION` > 0),
  CONSTRAINT `CHK_FB_CONTACTOS_DOCUMENTO` CHECK (char_length(trim(`DOCUMENTO_NORMALIZADO`)) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `FB_CONTACTOS_HISTORIAL` (
  `ID_HISTORIAL` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_CONTACTO` bigint(20) NOT NULL,
