  `DATOS_NUEVOS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`DATOS_NUEVOS`)),
  `FECHA_MODIFICACION` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`ID_HISTORIAL`),
  UNIQUE KEY `UK_CONTACTO_VERSION` (`ID_CONTACTO`,`VERSION`),
  KEY `IDX_CONTACTO_HIST_CONSULTA` (`ID_CONSULTA`),
  KEY `IDX_CONTACTO_HIST_FECHA` (`FECHA_MODIFICACION`),
  CONSTRAINT `FK_CONTACTO_HIST_CONSULTA` FOREIGN KEY (`ID_CONSULTA`) REFERENCES `FB_CIU_CONSULTAS_WEB` (`ID_CONSULTA`),
  CONSTRAINT `FK_CONTACTO_HIST_CONTACTO` FOREIGN KEY (`ID_CONTACTO`) REFERENCES `FB_CONTACTOS` (`ID_CONTACTO`),
  CONSTRAINT `CHK_CONTACTO_HIST_VERSION` CHECK (`VERSION` > 0)
