  CONSTRAINT `FK_FB_DOMICILIOS_CONSULTA` FOREIGN KEY (`ID_CONSULTA`) REFERENCES `FB_CIU_CONSULTAS_WEB` (`ID_CONSULTA`),
  CONSTRAINT `FK_FB_DOMICILIOS_PERSONA` FOREIGN KEY (`ID_PERSONA`) REFERENCES `FB_PERSONAS` (`ID_PERSONA`),
  CONSTRAINT `CHK_FB_DOMICILIOS_VERSION` CHECK (`VERSION` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
